/**
 * IcarusFlow Smart Contract Deployment Script
 * 
 * Deploys IcarusFlowCommit.sol to any EVM-compatible network.
 * Uses ethers.js v6 directly (no Hardhat dependency).
 * 
 * Usage:
 *   npm run deploy:contract
 * 
 * Required Environment Variables:
 *   WEIL_CHAIN_RPC_URL - RPC endpoint
 *   WEIL_PRIVATE_KEY   - Deployer private key
 */

import { ethers, ContractFactory } from 'ethers';
import * as dotenv from 'dotenv';
import * as fs from 'fs';
import * as path from 'path';
import { fileURLToPath } from 'url';

dotenv.config();

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Contract bytecode (compiled from IcarusFlowCommit.sol)
// This was compiled with solc 0.8.19
const CONTRACT_BYTECODE = `...`;

const CONTRACT_ABI = [
    {
        inputs: [
            { name: "flowId", type: "string" },
            { name: "workflowHash", type: "bytes32" },
            { name: "stateRoot", type: "bytes32" },
            { name: "auditLogHash", type: "bytes32" },
            { name: "taskCount", type: "uint256" }
        ],
        name: "commitWorkflow",
        outputs: [],
        stateMutability: "nonpayable",
        type: "function"
    },
    {
        inputs: [{ name: "flowId", type: "string" }],
        name: "exists",
        outputs: [{ name: "", type: "bool" }],
        stateMutability: "view",
        type: "function"
    },
    {
        inputs: [],
        name: "getTotalCommits",
        outputs: [{ name: "", type: "uint256" }],
        stateMutability: "view",
        type: "function"
    }
];

async function main() {
    console.log("\n" + "=".repeat(60));
    console.log("🚀 IcarusFlowCommit Contract Deployment");
    console.log("=".repeat(60) + "\n");

    // Check environment
    const rpcUrl = process.env.WEIL_CHAIN_RPC_URL;
    const privateKey = process.env.WEIL_PRIVATE_KEY;

    if (!rpcUrl || !privateKey) {
        console.log("❌ Error: Missing required environment variables\n");
        console.log("Please set the following in your .env file:");
        console.log("  WEIL_CHAIN_RPC_URL=your_rpc_url");
        console.log("  WEIL_PRIVATE_KEY=your_private_key\n");
        console.log("For testing, you can use a local Hardhat node or Sepolia testnet:");
        console.log("  WEIL_CHAIN_RPC_URL=https://rpc.sepolia.org");
        console.log("  WEIL_PRIVATE_KEY=0x...(your test private key)\n");
        process.exit(1);
    }

    try {
        // Connect to network
        console.log("📡 Connecting to network...");
        const provider = new ethers.JsonRpcProvider(rpcUrl);
        const network = await provider.getNetwork();
        console.log(`   Network: ${network.name} (Chain ID: ${network.chainId})\n`);

        // Setup wallet
        const wallet = new ethers.Wallet(privateKey, provider);
        console.log(`📝 Deployer: ${wallet.address}`);

        // Check balance
        const balance = await provider.getBalance(wallet.address);
        console.log(`💰 Balance: ${ethers.formatEther(balance)} ETH\n`);

        if (balance === 0n) {
            console.log("❌ Error: No funds for deployment\n");
            console.log("Get testnet ETH from:");
            console.log("  - Sepolia: https://sepoliafaucet.com/");
            console.log("  - WeilChain: (check WeilChain documentation)\n");
            process.exit(1);
        }

        // Deploy contract
        console.log("📦 Deploying IcarusFlowCommit contract...\n");

        const factory = new ContractFactory(CONTRACT_ABI, CONTRACT_BYTECODE, wallet);
        const contract = await factory.deploy();

        console.log(`⏳ Transaction submitted: ${contract.deploymentTransaction()?.hash}`);
        console.log("   Waiting for confirmation...\n");

        await contract.waitForDeployment();
        const contractAddress = await contract.getAddress();

        console.log("✅ Contract deployed successfully!\n");
        console.log(`📍 Contract Address: ${contractAddress}`);
        console.log(`🔗 Network: ${network.name}`);

        // Get deployment receipt
        const receipt = await contract.deploymentTransaction()?.wait();
        if (receipt) {
            console.log(`⛽ Gas Used: ${receipt.gasUsed.toString()}`);
            console.log(`📦 Block: ${receipt.blockNumber}`);
        }

        // Update .env file suggestion
        console.log("\n" + "=".repeat(60));
        console.log("📋 NEXT STEPS:");
        console.log("=".repeat(60));
        console.log("\n1. Add this to your .env file:\n");
        console.log(`   WEIL_CONTRACT_ADDRESS=${contractAddress}\n`);
        console.log("2. Run the demo to test real chain integration:\n");
        console.log("   npm run demo\n");
        console.log("=".repeat(60) + "\n");

        // Optionally update .env file
        const envPath = path.join(__dirname, '..', '.env');
        if (fs.existsSync(envPath)) {
            const envContent = fs.readFileSync(envPath, 'utf-8');
            if (!envContent.includes('WEIL_CONTRACT_ADDRESS')) {
                fs.appendFileSync(envPath, `\nWEIL_CONTRACT_ADDRESS=${contractAddress}\n`);
                console.log("✅ Added WEIL_CONTRACT_ADDRESS to .env file\n");
            }
        }

        return contractAddress;

    } catch (error) {
        console.error("\n❌ Deployment failed:", error);
        process.exit(1);
    }
}

main().then(() => {
    console.log("🎉 Deployment complete!\n");
    process.exit(0);
});
